-- Part 6 (diversification pass): MCQ top-up for supervision_manager. This role was sitting at
-- exactly 30 questions (the original seeding floor). Adds 24 further questions on topics NOT
-- already covered by mcq_part5_supervision_manager_seed.sql (verified by diffing topic lists):
-- QA vs QC distinction, surveillance vs 100% monitoring levels, witnessing commissioning tests,
-- NCR trend analysis, subcontractor technical audit, design-change field impact, as-built
-- verification, technical query (TQ) log management, sampling-frequency calculation.
-- Domain grounding: ISO 9001/19011 (QA/QC, audit), FIDIC Engineer's role, commissioning
-- witnessing practice, statistical sampling for inspection.
-- Same rotation technique as supabase/seed/mcq_questions_seed.sql. Idempotent via
-- (job_role, md5(stem_fa)) unique index.

insert into comp_mcq_questions (job_role, category, topic, difficulty, stem_fa, options, correct_option, explanation_fa, standard_ref, approval_status, active)
select 'supervision_manager', x ->> 0, x ->> 1, (x ->> 2)::smallint, x ->> 3,
  (select jsonb_agg(x -> 4 -> ((i - r.k + 4) % 4) order by i) from generate_series(0, 3) i),
  ((n - 1) % 4)::smallint, x ->> 6, x ->> 7, 'APPROVED', true
